session_start();require 'config/database.php';if(!isset($_SESSION['user'])){header('Location: login.php');exit;}$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT f.*,s.roll_no,u.name,p.name program_name FROM fee_challans f JOIN students s ON s.id=f.student_id JOIN users u ON u.id=s.user_id JOIN programs p ON p.id=s.program_id WHERE f.id=?');$q->execute([$id]);$f=$q->fetch();if(!$f){http_response_code(404);exit('Challan not found');}if($_SESSION['user']['role']==='student'){ $q=$pdo->prepare('SELECT id FROM students WHERE user_id=?'); $q->execute([(int)$_SESSION['user']['id']]); $owner=(int)$q->fetchColumn(); if($owner!== (int)$f['student_id']){http_response_code(403);exit('Access denied.');} } elseif($_SESSION['user']['role']!=='admin'){ http_response_code(403); exit('Access denied.'); }
$pageTitle='Fee Challan';require 'includes/header.php';?><div class="container py-5"><div class="card shadow-sm mx-auto" style="max-width:700px"><div class="card-body p-5"><div class="text-center"><h2>IMCB F-10/4</h2><p>Fee Challan / Receipt</p></div><hr><div class="row g-3"><div class="col-6"><strong>Challan No</strong><br><?=htmlspecialchars($f['challan_no'])?></div><div class="col-6"><strong>Date</strong><br><?=htmlspecialchars($f['issue_date'])?></div><div class="col-6"><strong>Student</strong><br><?=htmlspecialchars($f['name'])?></div><div class="col-6"><strong>Roll No</strong><br><?=htmlspecialchars($f['roll_no'])?></div><div class="col-6"><strong>Program</strong><br><?=htmlspecialchars($f['program_name'])?></div><div class="col-6"><strong>Purpose</strong><br><?=htmlspecialchars($f['purpose'])?></div><div class="col-12"><div class="border rounded p-3"><h4>Rs. <?=number_format($f['amount'],2)?></h4><div>Status: <?=htmlspecialchars(strtoupper($f['status']))?></div><div>Due Date: <?=htmlspecialchars($f['due_date'])?></div></div></div></div><div class="mt-4 text-center"><button class="btn btn-primary" onclick="window.print()">Print</button></div></div></div></div><?php require 'includes/footer.php';?>
